void StudioWindow::editTimeSessions(){
  if(bridge.busy()||projectData().isEmpty())return;
  auto project=projectData();const auto revision=view.value("revision"),root=view.value("root");const auto timing=project.value("progression").toObject();
  QDialog dialog(this);dialog.setObjectName("timeSessionsDialog");dialog.setWindowTitle(tr("시간 · 행동력 · 예약 사건"));dialog.resize(1060,740);auto box=new QVBoxLayout(&dialog);
  auto enabled=new QCheckBox(tr("시간·진행 세션 사용"));enabled->setObjectName("timeEnabled");enabled->setChecked(true);box->addWidget(enabled);
  auto help=new QLabel(tr("기존 독립 시계는 기존 진행 규칙을 유지합니다. 통합 시계는 일정 한 칸의 시간을 행동·대기와 공유하고 남은 시간을 월 일정으로 마칩니다. 개인 행동력은 시작 시, 일반 비용·효과는 완료 시 적용합니다. 취소는 시간·행동력을 반환하지 않습니다. 모델 변경 후 기존 저장은 별도 호환 검사가 필요합니다."));help->setWordWrap(true);box->addWidget(help);
  auto form=new QFormLayout;box->addLayout(form);auto unit=new QLineEdit(timing.value("unitLabel").toString(tr("시간")));unit->setMaxLength(20);unit->setObjectName("timeUnit");form->addRow(tr("시간 단위 이름"),unit);
  auto spin=[](int value,int min,int max,QString name){auto w=new QSpinBox;w->setRange(min,max);w->setValue(value);w->setObjectName(name);return w;};const auto ap=timing.value("actionPoints").toObject();
  auto model=new QComboBox;model->setObjectName("timeModel");model->addItem(tr("기존 · 독립 시계"),"legacy");model->addItem(tr("통합 · 월 일정 / 개인 시간 / 병렬 세션"),"unified-v2");model->setCurrentIndex(timing.value("model")=="unified-v2"?1:0);form->addRow(tr("진행 모델"),model);
  auto ticks=spin(timing.value("ticksPerPeriod").toInt(24),1,1000000,"timeTicksPerPeriod");form->addRow(tr("일정 한 칸의 시간 (통합)"),ticks);
  auto parallel=new QCheckBox(tr("다른 캐릭터의 시간 행동을 병렬 진행"));parallel->setObjectName("timeParallel");parallel->setChecked(timing.value("parallel").toBool());form->addRow(parallel);
  auto max=spin(ap.value("max").toInt(10),1,1000000,"timeApMax"),initial=spin(ap.value("initial").toInt(10),0,1000000,"timeApInitial"),recovery=spin(ap.value("recoveryPerTick").toInt(1),0,1000000,"timeApRecovery");form->addRow(tr("최대 행동력"),max);form->addRow(tr("초기 행동력"),initial);form->addRow(tr("시간 단위당 행동력 회복"),recovery);
  auto actions=new QTableWidget(0,4);actions->setObjectName("timedActions");actions->setHorizontalHeaderLabels({tr("시간 사용"),tr("공통 행동"),tr("소요 시간 / 수량 1"),tr("행동력 / 수량 1")});actions->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);box->addWidget(actions);
  for(const auto &v:project.value("gameplay").toObject().value("actions").toArray()){
    const auto a=v.toObject();const auto row=actions->rowCount();actions->insertRow(row);QJsonObject rule;for(const auto &t:timing.value("actions").toArray())if(t.toObject().value("actionId")==a.value("id"))rule=t.toObject();
    auto check=new QCheckBox;check->setChecked(!rule.empty());actions->setCellWidget(row,0,check);auto label=new QTableWidgetItem(a.value("name").toString());label->setData(Qt::UserRole,a.value("id").toString());label->setFlags(label->flags()&~Qt::ItemIsEditable);actions->setItem(row,1,label);actions->setCellWidget(row,2,spin(rule.value("duration").toInt(1),1,1000000,"duration"));actions->setCellWidget(row,3,spin(rule.value("actionPointCost").toInt(1),0,1000000,"actionPointCost"));
  }
  auto tabs=new QTabWidget;box->addWidget(tabs,1);box->removeWidget(actions);tabs->addTab(actions,tr("행동 시간"));
  auto actors=new QTableWidget(0,5);actors->setObjectName("timeActors");actors->setHorizontalHeaderLabels({tr("개별 설정"),tr("대상"),tr("최대 행동력"),tr("초기 행동력"),tr("시간당 회복")});actors->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);tabs->addTab(actors,tr("캐릭터 행동력"));
  auto actorName=[&](const QString&id){for(const auto &v:view.value("documents").toArray()){const auto d=v.toObject(),a=d.value("data").toObject();if(d.value("kind")=="character"&&a.value("id")==id)return a.value("name").toString(id)+" ["+id+"]";}return id;};
  auto members=project.value("roster").toObject().value("members").toArray();if(members.isEmpty())members.append(QJsonObject{{"characterId",project.value("protagonistId")}});
  for(const auto &m:members){const auto id=m.toObject().value("characterId").toString();QJsonObject settings;for(const auto &p:timing.value("actorPools").toArray())if(p.toObject().value("actorId")==id)settings=p.toObject();int row=actors->rowCount();actors->insertRow(row);auto use=new QCheckBox;use->setChecked(!settings.empty());actors->setCellWidget(row,0,use);auto name=new QTableWidgetItem(actorName(id));name->setData(Qt::UserRole,id);name->setFlags(name->flags()&~Qt::ItemIsEditable);actors->setItem(row,1,name);if(settings.empty())settings=ap;actors->setCellWidget(row,2,spin(settings.value("max").toInt(10),1,1000000,"actorApMax"));actors->setCellWidget(row,3,spin(settings.value("initial").toInt(10),0,1000000,"actorApInitial"));actors->setCellWidget(row,4,spin(settings.value("recoveryPerTick").toInt(1),0,1000000,"actorApRecovery"));}
  auto activities=new QTableWidget(0,3);activities->setObjectName("timedActivities");activities->setHorizontalHeaderLabels({tr("비용 설정"),tr("일정 활동"),tr("실행자별 행동력")});activities->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);tabs->addTab(activities,tr("월 일정"));
  for(const auto &d:view.value("documents").toArray())if(d.toObject().value("kind")=="activity"){const auto a=d.toObject().value("data").toObject();QJsonObject rule;for(const auto &v:timing.value("activities").toArray())if(v.toObject().value("activityId")==a.value("id"))rule=v.toObject();int row=activities->rowCount();activities->insertRow(row);auto use=new QCheckBox;use->setChecked(!rule.empty());activities->setCellWidget(row,0,use);auto label=new QTableWidgetItem(a.value("label").toString()+" ["+a.value("id").toString()+"]");label->setData(Qt::UserRole,a.value("id").toString());label->setFlags(label->flags()&~Qt::ItemIsEditable);activities->setItem(row,1,label);activities->setCellWidget(row,2,spin(rule.value("actionPointCost").toInt(),0,1000000,"activityApCost"));}
  auto page=new QWidget;auto reservationBox=new QVBoxLayout(page);tabs->addTab(page,tr("예약 · 반복"));
  auto appointments=new QTableWidget(0,6);appointments->setObjectName("timeAppointments");appointments->setHorizontalHeaderLabels({tr("예약 ID"),tr("사건"),tr("첫 게임 시각"),tr("개인 사건 실행자"),tr("반복 간격 (0=한 번)"),tr("총 횟수")});appointments->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);reservationBox->addWidget(appointments);
  auto addRow=[&](const QJsonObject &a){const int row=appointments->rowCount();appointments->insertRow(row);appointments->setItem(row,0,new QTableWidgetItem(a.value("id").toString("appointment-"+QString::number(row+1))));auto event=new QComboBox;for(const auto &v:view.value("documents").toArray()){const auto d=v.toObject(),data=d.value("data").toObject();if(d.value("kind")=="event"&&data.value("trigger")=="interaction")event->addItem(data.value("label").toString(),data.value("id").toString());}if(a.contains("eventId"))event->setCurrentIndex(event->findData(a.value("eventId").toString()));appointments->setCellWidget(row,1,event);appointments->setCellWidget(row,2,spin(a.value("atTick").toInt(),0,2147483647,"atTick"));auto actor=new QComboBox;actor->addItem(tr("공용 사건"),QString());for(const auto &m:project.value("roster").toObject().value("members").toArray()){const auto id=m.toObject().value("characterId").toString();actor->addItem(actorName(id),id);}actor->setCurrentIndex(qMax(0,actor->findData(a.value("actorId").toString())));appointments->setCellWidget(row,3,actor);appointments->setCellWidget(row,4,spin(a.value("repeatEvery").toInt(),0,1000000,"repeatEvery"));appointments->setCellWidget(row,5,spin(a.value("repeatCount").toInt(1),1,1000,"repeatCount"));};
  for(const auto &a:timing.value("appointments").toArray())addRow(a.toObject());
  auto rowButtons=new QHBoxLayout;reservationBox->addLayout(rowButtons);auto add=new QPushButton(tr("＋ 예약 사건"));add->setObjectName("addTimeAppointment");rowButtons->addWidget(add);connect(add,&QPushButton::clicked,&dialog,[&]{addRow({});});auto remove=new QPushButton(tr("선택 예약 삭제"));remove->setObjectName("removeTimeAppointment");rowButtons->addWidget(remove);connect(remove,&QPushButton::clicked,&dialog,[&]{if(appointments->currentRow()>=0)appointments->removeRow(appointments->currentRow());});
  auto refresh=[&]{const bool v2=model->currentIndex()==1;ticks->setEnabled(v2);parallel->setEnabled(v2);actors->setEnabled(v2);activities->setEnabled(v2);};connect(model,&QComboBox::currentIndexChanged,&dialog,refresh);refresh();
  auto error=new QLabel;error->setObjectName("timeError");error->setWordWrap(true);box->addWidget(error);auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);box->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);
  connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{
    if(view.value("revision")!=revision||view.value("root")!=root){error->setText(tr("프로젝트 버전이 바뀌었습니다. 창을 다시 여세요."));return;}
    if(enabled->isChecked()){
      if(unit->text().trimmed().isEmpty()||initial->value()>max->value()){error->setText(tr("시간 단위와 행동력 범위를 확인하세요."));return;}
      QJsonArray rules,reservations;for(int i=0;i<actions->rowCount();i++)if(qobject_cast<QCheckBox*>(actions->cellWidget(i,0))->isChecked())rules.append(QJsonObject{{"actionId",actions->item(i,1)->data(Qt::UserRole).toString()},{"duration",qobject_cast<QSpinBox*>(actions->cellWidget(i,2))->value()},{"actionPointCost",qobject_cast<QSpinBox*>(actions->cellWidget(i,3))->value()}});
      for(int i=0;i<appointments->rowCount();i++){if(appointments->item(i,0)->text().trimmed().isEmpty()||qobject_cast<QComboBox*>(appointments->cellWidget(i,1))->currentData().toString().isEmpty()){error->setText(tr("예약 %1행: 예약 ID와 사건을 선택하세요.").arg(i+1));return;}QJsonObject a{{"id",appointments->item(i,0)->text().trimmed()},{"eventId",qobject_cast<QComboBox*>(appointments->cellWidget(i,1))->currentData().toString()},{"atTick",qobject_cast<QSpinBox*>(appointments->cellWidget(i,2))->value()}};const auto actor=qobject_cast<QComboBox*>(appointments->cellWidget(i,3))->currentData().toString();if(!actor.isEmpty())a["actorId"]=actor;const int every=qobject_cast<QSpinBox*>(appointments->cellWidget(i,4))->value(),count=qobject_cast<QSpinBox*>(appointments->cellWidget(i,5))->value();if((every>0&&(model->currentIndex()!=1||count<2))||(every==0&&count!=1)){error->setText(tr("반복 예약에는 통합 모드·간격·2회 이상 횟수가 필요합니다."));return;}if(every){a["repeatEvery"]=every;a["repeatCount"]=count;}reservations.append(a);}
      project["progression"]=QJsonObject{{"unitLabel",unit->text().trimmed()},{"actionPoints",QJsonObject{{"max",max->value()},{"initial",initial->value()},{"recoveryPerTick",recovery->value()}}},{"actions",rules},{"appointments",reservations}};
      if(model->currentIndex()==1){QJsonArray pools,costs;for(int i=0;i<actors->rowCount();++i)if(qobject_cast<QCheckBox*>(actors->cellWidget(i,0))->isChecked()){const int maximum=qobject_cast<QSpinBox*>(actors->cellWidget(i,2))->value(),start=qobject_cast<QSpinBox*>(actors->cellWidget(i,3))->value();if(start>maximum){error->setText(tr("개인 초기 행동력이 최대값보다 큽니다."));return;}pools.append(QJsonObject{{"actorId",actors->item(i,1)->data(Qt::UserRole).toString()},{"max",maximum},{"initial",start},{"recoveryPerTick",qobject_cast<QSpinBox*>(actors->cellWidget(i,4))->value()}});}for(int i=0;i<activities->rowCount();++i)if(qobject_cast<QCheckBox*>(activities->cellWidget(i,0))->isChecked())costs.append(QJsonObject{{"activityId",activities->item(i,1)->data(Qt::UserRole).toString()},{"actionPointCost",qobject_cast<QSpinBox*>(activities->cellWidget(i,2))->value()}});auto v=project.value("progression").toObject();v["model"]="unified-v2";v["ticksPerPeriod"]=ticks->value();v["parallel"]=parallel->isChecked();v["actorPools"]=pools;v["activities"]=costs;project["progression"]=v;}
    }else project.remove("progression");
    replaceProject(project);dialog.accept();
  });dialog.exec();
}
